sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    // FLEET-19: defaults, field validation, short description and task.active (D-01, D-03, D-20, D-26)
    var CLOSED = ['COMPLETED', 'CANCELLED', 'REJECTED', 'NO_SHOW']; // INTERRUPTED is closed by FLEET-42
    var DIRECTOR = 'x_1850693_enterp_0.director';

    var isInsert = current.operation() == 'insert';
    var state = current.getValue('reservation_state');
    var stateChanged = isInsert || current.reservation_state.changes();
    var errors = [];

    // Requester-derived defaults
    if (isInsert || current.requested_by.changes()) {
        var req = current.requested_by.getRefRecord();
        if (!req.isValidRecord()) {
            errors.push('Requested By is required.');
        } else {
            if (req.manager.nil()) {
                errors.push('Requester ' + req.getDisplayValue() + ' has no manager, so the reservation cannot be routed for approval.');
            } else {
                current.setValue('manager_approver', req.getValue('manager'));
            }
            if (current.requested_depot.nil() && !req.location.nil()) {
                current.setValue('requested_depot', req.getValue('location'));
            }
            if (isInsert && current.assigned_driver.nil()) {
                current.setValue('assigned_driver', req.getUniqueValue());
            }
        }
    }

    // requested_by / cost_center read-only after DRAFT (except director/admin)
    if (!isInsert && previous.getValue('reservation_state') != 'DRAFT' &&
        (current.requested_by.changes() || current.cost_center.changes()) && !gs.hasRole(DIRECTOR)) {
        errors.push('Requested By and Cost Center cannot be changed after the reservation leaves DRAFT.');
    }

    // Dates: start lead and end > start for requests are FleetReservationValidator V1/V2 (FLEET-30);
    // end > start is still enforced here once the reservation is past approval.
    var start = current.start_datetime.nil() ? null : new GlideDateTime(current.getValue('start_datetime'));
    var end = current.end_datetime.nil() ? null : new GlideDateTime(current.getValue('end_datetime'));
    var requestState = state == 'DRAFT' || state == 'PENDING_APPROVAL' || (isInsert && !current.replaces_reservation.nil());
    if (!requestState && start && end && end.compareTo(start) <= 0) {
        errors.push('End must be after start.');
    }

    if (!current.estimated_miles.nil() && parseInt(current.getValue('estimated_miles'), 10) <= 0) {
        errors.push('Estimated Miles must be greater than 0.');
    }

    if (!current.priority_override.nil()) {
        var p = parseInt(current.getValue('priority_override'), 10);
        if (p < 1 || p > 5) {
            errors.push('Priority Override must be between 1 and 5.');
        }
    }

    // State-dependent mandatory fields
    if (state == 'CANCELLED' && !(current.getValue('cancellation_reason') || '').trim()) {
        errors.push('Cancellation Reason is required to cancel a reservation.');
    }
    if (stateChanged && state == 'ACTIVE' && current.check_out_odometer.nil()) {
        errors.push('Check-out Odometer is required to start the trip.');
    }
    if (stateChanged && state == 'COMPLETED') {
        if (current.check_in_odometer.nil()) {
            errors.push('Check-in Odometer is required to complete the trip.');
        } // check-in vs check-out odometer: FLEET - Validate Check-in (FLEET-35)
    }

    if (errors.length) {
        for (var i = 0; i < errors.length; i++) {
            gs.addErrorMessage(errors[i]);
        }
        current.setAbortAction(true);
        return;
    }

    current.setValue('short_description', current.vehicle_category.getDisplayValue() + ' reservation ' +
        current.start_datetime.getDisplayValue() + ' - ' + current.end_datetime.getDisplayValue());

    // D-01: task.active follows reservation_state
    if (CLOSED.indexOf(state) > -1) {
        current.setValue('active', false);
    }
})(current, previous);
